namespace ghidra.feature.vt.gui.actions;

using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.util;
using docking;
using docking.action;
using docking.action;
using docking.tool;

public class CloseVersionTrackingSessionAction : DockingAction {

	private VTController controller;

	public CloseVersionTrackingSessionAction(VTController controller) : base("Close Session", VTPlugin.OWNER)
    {
		this.controller = controller;
		string[] menuPath = new string[] { ToolConstants.MENU_FILE, "Close Session..." };
		setMenuBarData(new MenuData(menuPath, "AAB"));
		setDescription("Closes the current Version Tracking Session");
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Version_Tracking_Tool"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		controller.closeVersionTrackingSession();

	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return controller.getSession() != null;
	}

}
